"""Ideal power-sum equalities in degrees 1-5, and the descent of the invariant m(N,3).

This script certifies, by direct integer arithmetic, every witness used in the
determination of the minimal collision size in small degree:

  degree 1: {0,2}                vs {1,1}              -- alphabet {0,...,2}
  degree 2: {0,3,3}              vs {1,1,4}            -- alphabet {0,...,4}
  degree 3: {1,1,6,6}            vs {0,3,4,7}          -- alphabet {0,...,7}
  degree 4: {0,4,8,16,17}        vs {1,2,10,14,18}     -- alphabet {0,...,18}
  degree 5: {0,3,5,11,13,16}     vs {1,1,8,8,15,15}    -- alphabet {0,...,16}

each with exactly K + 1 elements per side, hence attaining the Prouhet-Tarry-Escott
floor, so that m(N,K) = K + 1 for every alphabet at least as wide.  It also verifies
the two intermediate witnesses that push the invariant below the Prouhet ceiling 2^K
long before the ideal alphabet is reached, and recomputes the full degree-3 descent
m(4,3) = 8, m(5,3) = 6, m(6,3) = 6, m(7,3) = 4 by exhaustive search over disjoint
pairs (justified because the common part of a collision can always be deleted).
"""

from __future__ import annotations

from itertools import combinations, combinations_with_replacement
from typing import Dict, List, Optional, Sequence, Tuple

IDEAL: Dict[int, Tuple[List[int], List[int]]] = {
    1: ([0, 2], [1, 1]),
    2: ([0, 3, 3], [1, 1, 4]),
    3: ([1, 1, 6, 6], [0, 3, 4, 7]),
    4: ([0, 4, 8, 16, 17], [1, 2, 10, 14, 18]),
    5: ([0, 3, 5, 11, 13, 16], [1, 1, 8, 8, 15, 15]),
}

INTERMEDIATE: List[Tuple[int, List[int], List[int]]] = [
    (3, [1, 1, 1, 4, 4, 4], [0, 2, 2, 3, 3, 5]),
    (4, [1, 1, 1, 5, 6, 6, 8], [0, 2, 2, 3, 7, 7, 7]),
]


def power_sum(data: Sequence[int], k: int) -> int:
    return sum(x ** k for x in data)


def certify(K: int, s: Sequence[int], t: Sequence[int]) -> bool:
    """Verify: equal cardinalities, equal power sums for all k <= K, distinct at K+1."""
    if len(s) != len(t):
        return False
    if any(power_sum(s, k) != power_sum(t, k) for k in range(K + 1)):
        return False
    return power_sum(s, K + 1) != power_sum(t, K + 1)


def find_collision(N: int, K: int, n: int) -> Optional[Tuple[tuple, tuple]]:
    buckets: Dict[tuple, List[tuple]] = {}
    for combo in combinations_with_replacement(range(N + 1), n):
        buckets.setdefault(tuple(power_sum(combo, k) for k in range(K + 1)), []).append(combo)
    for group in buckets.values():
        for a, b in combinations(group, 2):
            if not (set(a) & set(b)):
                return a, b
    return None


def min_collision_card(N: int, K: int) -> int:
    if N <= K:
        return 0
    for n in range(K + 1, 2 ** K + 1):
        if find_collision(N, K, n) is not None:
            return n
    return 2 ** K


def main() -> None:
    print("IDEAL WITNESSES (size K+1: the Prouhet-Tarry-Escott floor)")
    print("-" * 72)
    for K, (s, t) in IDEAL.items():
        D = max(max(s), max(t))
        sums = [power_sum(s, k) for k in range(K + 1)]
        print(f"  degree {K}  {s} vs {t}   alphabet bound {D}")
        print(f"      shared power sums k = 0..{K}: {sums}")
        print(f"      order {K+1}: {power_sum(s, K+1)} vs {power_sum(t, K+1)}")
        print(f"      certified: {certify(K, s, t)}  =>  m(N,{K}) = {K+1} for all N >= {D}")

    print("\nINTERMEDIATE WITNESSES (below the ceiling 2^K, above the floor K+1)")
    print("-" * 72)
    for K, s, t in INTERMEDIATE:
        D = max(max(s), max(t))
        print(f"  degree {K}  {s} vs {t}  size {len(s)} < {2**K} = 2^K, alphabet bound {D}")
        print(f"      certified: {certify(K, s, t)}  =>  m(N,{K}) <= {len(s)} for all N >= {D}")

    print("\nEXHAUSTIVE DESCENT OF m(N,3) FROM THE CEILING 8 TO THE FLOOR 4")
    print("-" * 72)
    for N in range(3, 9):
        m = min_collision_card(N, 3)
        label = "rigid (no collision)" if m == 0 else ""
        print(f"  m({N}, 3) = {m}  {label}")
    print("\n  the minimising pair found at N = 7:", find_collision(7, 3, 4))


if __name__ == "__main__":
    main()

