INPUT : N, exact moments S[0..N]
OUTPUT: weights w[0..N] on the nodes 0,1,...,N

function LAGRANGE_COEFFS(N, j):
    poly   <- [1]                       # coefficient list, low order first
    denom  <- 1
    for i in 0..N, i != j:
        poly  <- [0] ++ poly            # multiply by X
        for d in 0..len(poly)-2:        # subtract i * (previous polynomial)
            poly[d] <- poly[d] - i * poly[d+1]
        denom <- denom * (j - i)
    return [c / denom for c in poly]

function INVERT_MOMENTS(N, S):
    for j in 0..N:
        c    <- LAGRANGE_COEFFS(N, j)
        w[j] <- sum_{k=0..N} c[k] * S[k]
    return w

function STABILITY(N, j):
    return sum of |c| over c in LAGRANGE_COEFFS(N, j)
    # guarantee: |w_j - v_j| <= STABILITY(N,j) * eps whenever every moment
    #            of order k <= N is known to within eps

